const LS_KEYS = {
  PINNED: "bm_pinned_services",
  RECENT: "bm_recent_services",
  MOST_USED: "bm_most_used_services",
  USAGE_COUNTS: "bm_usage_counts",
};

// mostUsed is always derived from raw { serviceId: count } usage data plus
// the current service list — never read/written directly as an array in
// localStorage, so it can never end up as a non-array value.
const getUsageCounts = () => {
  const raw = getLS(LS_KEYS.USAGE_COUNTS, {});
  return raw && typeof raw === "object" && !Array.isArray(raw) ? raw : {};
};

const deriveMostUsed = (usageCounts, serviceList) => {
  return Object.entries(usageCounts)
    .sort((a, b) => b[1] - a[1])
    .map(([id]) => serviceList.find((s) => s._id === id))
    .filter(Boolean)
    .slice(0, MAX_MOST_USED);
};

